    int batchSize = 100;
    int recSize = 1024;
    // First entry.
    long ledgerIndex = 1;
    long entryIndex = 0;
    long slotIndex = 0;
    long txIndex = 1;
    checkAllSucceeded(writer, batchSize, recSize, ledgerIndex, entryIndex, slotIndex, txIndex);
    // New entry.
    entryIndex++;
    slotIndex = 0;
    txIndex += batchSize;
    checkAllSucceeded(writer, batchSize, recSize, ledgerIndex, entryIndex, slotIndex, txIndex);
    // Roll ledger.
    ledgerIndex++;
    entryIndex = 0;
    slotIndex = 0;
    txIndex += batchSize;
    writer.closeAndComplete();
    writer = (BKAsyncLogWriter) (dlm.startAsyncLogSegmentNonPartitioned());
    checkAllSucceeded(writer, batchSize, recSize, ledgerIndex, entryIndex, slotIndex, txIndex);
    writer.closeAndComplete();
    dlm.close();
}

