        assertEquals(currentLogSegmentSeqNo, dlsn.getLogSegmentSequenceNo());
        assertEquals(0, dlsn.getEntryId());
        assertEquals(0, dlsn.getSlotId());
        for (long j = 1; j < 10; j++) {
