            expectedTxId += 2;
        } else {
            ++expectedTxId;
        }
        record = reader.readNext(false);
    }
    reader.close();
    assertEquals(3 * 9, numTrans);
    assertEquals(3 * 9, readDlm.getLogRecordCount());
