@Test(timeout = 60000)
public void testStartWithEmptySegmentList() throws Exception {
    String streamName = runtime.getMethodName();
    BKDistributedLogManager dlm = createNewDLM(baseConf, streamName);
    ReadAheadEntryReader readAheadEntryReader = createEntryReader(streamName, DLSN.InitialDLSN, dlm, baseConf);
    readAheadEntryReader.start(Lists.<LogSegmentMetadata>newArrayList());
    ensureOrderSchedulerEmpty(streamName);
    assertFalse("ReadAhead should not be initialized with empty segment list", readAheadEntryReader.isInitialized());
    assertTrue("ReadAhead should be empty when it isn't initialized", readAheadEntryReader.isCacheEmpty());
    assertFalse("ReadAhead should not be marked as caught up when it isn't initialized", readAheadEntryReader.isReadAheadCaughtUp());
    // generate list of log segments
    generateCompletedLogSegments(dlm, 1, MAX_CACHED_ENTRIES / 2 + 1);
    List<LogSegmentMetadata> segments = dlm.getLogSegments();
    assertEquals(segments.size() + " log segments found, expected to be only one", 1, segments.size());
    // notify the readahead reader with new segment lsit
    readAheadEntryReader.onSegmentsUpdated(segments);
    // check the reader state after initialization
    ensureOrderSchedulerEmpty(streamName);
    assertTrue("ReadAhead should be initialized with non-empty segment list", readAheadEntryReader.isInitialized());
    assertNotNull("current segment reader should be initialized", readAheadEntryReader.getCurrentSegmentReader());
    assertEquals("current segment sequence number should be " + segments.get(0).getLogSegmentSequenceNumber(), segments.get(0).getLogSegmentSequenceNumber(), readAheadEntryReader.getCurrentSegmentSequenceNumber());
    assertNull("there should be no next segment reader", readAheadEntryReader.getNextSegmentReader());
    assertTrue("there should be no remaining segment readers", readAheadEntryReader.getSegmentReaders().isEmpty());
    Utils.close(readAheadEntryReader);
    dlm.close();
}

